import React, { useState } from 'react'


//Displays all the tasks
const ToDoItem = (TodoArray, toggleCompleted, deleteTodo) => {
  return (
    <div>
      <li>
      {/* main content */}
      {TodoArray.text}
      {/* complete buttton */}
      <button onClick={toggleCompleted(TodoArray.id)}>
        {/* function to determine if we should write undo or complete in the button */}
        {()=>{
          if(TodoArray.completed){
            return("Undo")
          }
          else{
            return("Complete")
          }
        }}
        {/* delete button */}
      </button>
      <button onClick={deleteTodo(TodoArray.id)}>Delete</button>
      </li>
    </div>
  )
}

export default ToDoItem
